{
  "story": "The client and server establish a reliable connection through a three-step sequence, exchanging synchronization and acknowledgment flags before data flows.",
  "aha": {
    "stateId": "ack",
    "observation": "Both client and server have acknowledged each other's sequence numbers, completing the handshake and opening the connection."
  },
  "layout": {
    "preset": "stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Handshake Step",
      "options": [
        "SYN",
        "SYN-ACK",
        "ACK"
      ]
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Restart"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "TCP Handshake",
        "regions": [
          {
            "id": "client",
            "label": "Client",
            "kind": "actor",
            "values": ["CLOSED", "SYN_SENT", "ESTABLISHED"]
          },
          {
            "id": "server",
            "label": "Server",
            "kind": "actor",
            "values": ["LISTEN", "SYN_RCVD", "ESTABLISHED"]
          }
        ],
        "links": [
          {
            "from": "client",
            "to": "server",
            "label": "packet"
          }
        ],
        "states": [
          {
            "id": "syn",
            "label": "1. SYN",
            "short": "SYN",
            "sentence": "The client sends a SYN packet to initiate the connection.",
            "why": "Client proposes initial sequence number.",
            "active": ["client"],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "cstate",
                "label": "Client State",
                "value": "SYN_SENT"
              },
              {
                "id": "sstate",
                "label": "Server State",
                "value": "LISTEN"
              }
            ]
          },
          {
            "id": "syn-ack",
            "label": "2. SYN-ACK",
            "short": "SYN-ACK",
            "sentence": "The server replies with SYN-ACK, acknowledging the client's request.",
            "why": "Server acknowledges client and sends its own SYN.",
            "active": ["server"],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "cstate",
                "label": "Client State",
                "value": "SYN_SENT"
              },
              {
                "id": "sstate",
                "label": "Server State",
                "value": "SYN_RCVD"
              }
            ]
          },
          {
            "id": "ack",
            "label": "3. ACK",
            "short": "ACK",
            "sentence": "The client sends an ACK, confirming the server's sequence number.",
            "why": "Connection is fully established for data transfer.",
            "active": ["client", "server"],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "cstate",
                "label": "Client State",
                "value": "ESTABLISHED"
              },
              {
                "id": "sstate",
                "label": "Server State",
                "value": "ESTABLISHED"
              }
            ]
          }
        ]
      }
    ]
  }
}
